from enum import Enum


class OrderState(Enum):
    CREATED = "created"
    PAID = "paid"
    SHIPPED = "shipped"
    DELIVERED = "delivered"
    CANCELLED = "cancelled"
    REFUNDED = "refunded"


S = OrderState

# Legal transitions. States mapped to an empty set are terminal.
TRANSITIONS = {
    S.CREATED: {S.PAID, S.CANCELLED},
    S.PAID: {S.SHIPPED, S.REFUNDED},
    S.SHIPPED: {S.DELIVERED},
    S.DELIVERED: {S.REFUNDED},
    S.CANCELLED: set(),
    S.REFUNDED: set(),
}


class InvalidTransition(Exception):
    def __init__(self, current, target):
        self.current = current
        self.target = target
        super().__init__(f"cannot go from {current.value} to {target.value}")


class Order:
    def __init__(self, order_id):
        self.id = order_id
        self.state = S.CREATED
        self.history = [S.CREATED]

    def can_transition(self, target):
        return target in TRANSITIONS[self.state]

    def transition(self, target):
        if not self.can_transition(target):
            raise InvalidTransition(self.state, target)
        self.state = target
        self.history.append(target)

    def pay(self):
        self.transition(S.PAID)

    def ship(self):
        self.transition(S.SHIPPED)

    def deliver(self):
        self.transition(S.DELIVERED)

    def cancel(self):
        self.transition(S.CANCELLED)

    def refund(self):
        self.transition(S.REFUNDED)

    @property
    def is_terminal(self):
        return not TRANSITIONS[self.state]

import unittest

from order import TRANSITIONS, InvalidTransition, Order, OrderState as S


def order_in(state):
    """Build an order already in the given state, bypassing transitions."""
    order = Order("o1")
    order.state = state
    return order


class OrderTest(unittest.TestCase):
    def test_starts_created(self):
        self.assertEqual(Order("o1").state, S.CREATED)

    def test_happy_path(self):
        order = Order("o1")
        order.pay()
        order.ship()
        order.deliver()
        order.refund()
        self.assertEqual(
            order.history,
            [S.CREATED, S.PAID, S.SHIPPED, S.DELIVERED, S.REFUNDED],
        )
        self.assertTrue(order.is_terminal)

    def test_every_pair(self):
        # Exhaustive: all 36 (source, target) pairs match the table.
        for source in S:
            for target in S:
                order = order_in(source)
                if target in TRANSITIONS[source]:
                    order.transition(target)
                    self.assertEqual(order.state, target)
                else:
                    with self.assertRaises(InvalidTransition):
                        order.transition(target)
                    self.assertEqual(order.state, source)
                    self.assertEqual(order.history, [S.CREATED])

    def test_error_message(self):
        with self.assertRaises(InvalidTransition) as ctx:
            Order("o1").ship()
        self.assertEqual(str(ctx.exception), "cannot go from created to shipped")


if __name__ == "__main__":
    unittest.main()
